// CHANGE-ME: Zammad-Gruppe + Requester ggf. anpassen (siehe docs/f-cicd-automatisierung/f0040-github-release-watcher.md fuer die Regeln dazu -- ZAMMAD_REQUESTER_EMAIL muss ein bereits existierender Zammad-User sein).
const ZAMMAD_GROUP = 'Support::Administration';
const ZAMMAD_REQUESTER_EMAIL = 'info@edv-kretzer.de';

// Wie lange (ms) ein inhaltsgleicher Alarm als Duplikat gilt -- schuetzt
// gegen Mehrfach-Tickets, falls der AMweb-Webhook pro offenem Kiosk-Tab
// feuert (bis zu 3 Standorte moeglich, siehe
// docs/4-planung/40060-alamos-einsatz-email-benachrichtigung.md,
// offene Punkte -- ob das tatsaechlich passiert, war ohne Alamos-Login
// nicht abschliessend zu klaeren).
const DEDUP_WINDOW_MS = 2 * 60 * 1000;

// Beide Webhook-Trigger-Varianten (GET-Query-Parameter ODER POST-JSON-Body)
// zusammenfuehren -- welche Variante ihr in AMweb konfiguriert (AMweb-Seiten-
// Webhook vs. "Allgemeine Webhooks"), war ohne Alamos-Login nicht
// abschliessend zu klaeren, siehe docs/4-planung/40060-....
const raw = $input.item.json;
const merged = { ...(raw.query || {}), ...(raw.body || {}) };

// Bekannte Platzhalter laut Alamos-Handbuch (Allgemeine Webhooks): "keyword"
// und "unit". Weitere Feldnamen (Adresse, Fahrzeuge, Meldebild, ...) sind
// nur in der eingeloggten Webhook-Vorschau/"Webhook Test" des
// Alamos-Accounts einsehbar -- deshalb werden unten ALLE empfangenen Felder
// unveraendert mit ausgegeben, nicht nur eine feste Vorauswahl ("alle Daten
// die moeglich sind abgreifen").
const keyword = merged.keyword || merged.stichwort || merged.Stichwort || null;
const unit = merged.unit || merged.station || null;

// Weder keyword noch unit vorhanden -- kein echter Einsatzalarm, sondern
// z.B. ein Verbindungstest/Health-Check gegen alamos-relay/den Webhook
// (leerer GET-Call ohne Query-Parameter, curl-Test, Alamos-"Webhook Test"
// ohne echte Auswahl). Kein Ticket, aber sichtbar im Execution-Log, damit
// ein echter Alarm mit unerwarteten Feldnamen nicht denselben Weg lautlos
// nimmt und unbemerkt durchrutscht.
if (!keyword && !unit) {
  console.log('Kein keyword/unit im Payload -- vermutlich Test-Call, kein Ticket. Rohdaten:', JSON.stringify(merged));
  return [];
}

const title = keyword
  ? `ALAMOS-Einsatzalarm: ${keyword}${unit ? ` (${unit})` : ''}`
  : `ALAMOS-Einsatzalarm${unit ? ` (${unit})` : ''}`;

const fieldLines = Object.entries(merged)
  .map(([key, value]) => `- ${key}: ${typeof value === 'object' ? JSON.stringify(value) : value}`)
  .join('\n');

const bodyText = [
  'Neuer Einsatzalarm von ALAMOS AMweb.',
  '',
  'Empfangene Rohdaten (alles, was der Webhook mitgeliefert hat):',
  fieldLines,
  '',
  `Empfangen: ${new Date().toISOString()}`,
].join('\n');

// Duplikat-Schutz ueber Workflow-Static-Data (ueberlebt einzelne
// Workflow-Laeufe, aber keinen n8n-Neustart -- fuer den Zweck ausreichend,
// da echte Mehrfach-Ausloesungen desselben Alarms innerhalb von Sekunden
// eintreffen wuerden, nicht erst nach einem Neustart).
const staticData = $getWorkflowStaticData('node');
staticData.recentAlarms = staticData.recentAlarms || {};

const dedupKey = keyword && unit ? `${keyword}|${unit}` : JSON.stringify(merged);
const now = Date.now();

for (const [existingKey, ts] of Object.entries(staticData.recentAlarms)) {
  if (now - ts > DEDUP_WINDOW_MS) delete staticData.recentAlarms[existingKey];
}

if (staticData.recentAlarms[dedupKey] !== undefined) {
  // Duplikat innerhalb des Zeitfensters -- kein zweites Ticket erzeugen.
  return [];
}
staticData.recentAlarms[dedupKey] = now;

return [{
  json: {
    title,
    group: ZAMMAD_GROUP,
    customer: ZAMMAD_REQUESTER_EMAIL,
    body: bodyText,
  },
}];

const MAIL_AN = 'peter.kretzer@dlrg.org';
const MAIL_VON = 'workflow-n8n@edv-kretzer.de';
const ID_ZEILE = 'ID-IT-xi8klGKdh8';
const SCHRIFT = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const FARBEN = { rot: '#c8102e', amber: '#b45309', gruen: '#15803d', blau: '#1d4ed8', grau: '#475569', indigo: '#4338ca' };
const mitId = (text) => String(text).replace(/\s+$/, '') + '\n\n' + ID_ZEILE;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const verlinken = (s) => esc(s).replace(/(https?:\/\/[^\s<]*[^\s<.,;:!?)])/g, '<a href="$1" style="color:#1d4ed8;text-decoration:underline">$1</a>');
const absaetze = (text) => String(text).replace(/\r\n?/g, '\n').split(/\n{2,}/).filter((b) => b.trim()).map((b) => '<p style="margin:0 0 14px 0;line-height:1.6">' + verlinken(b.trim()).replace(/\n/g, '<br>') + '</p>').join('');
const felder = (zeilen) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 18px 0;border:1px solid #e5e7eb">' + zeilen.map(([k, v], i) => '<tr style="background:' + (i % 2 ? '#ffffff' : '#f9fafb') + '"><td valign="top" style="padding:9px 12px;width:34%;font-size:13px;color:#6b7280;border-bottom:1px solid #eef0f3">' + esc(k) + '</td><td valign="top" style="padding:9px 12px;font-size:14px;color:#111827;border-bottom:1px solid #eef0f3">' + verlinken(v) + '</td></tr>').join('') + '</table>';
const box = (inhalt, farbe, titel) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 18px 0"><tr><td style="border-left:4px solid ' + farbe + ';background:#f9fafb;padding:14px 16px">' + (titel ? '<div style="font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:' + farbe + ';margin-bottom:8px">' + esc(titel) + '</div>' : '') + inhalt + '</td></tr></table>';
const liste = (eintraege) => '<ul style="margin:0;padding:0 0 0 18px;line-height:1.6">' + eintraege.map((e) => '<li style="margin:0 0 4px 0">' + verlinken(e) + '</li>').join('') + '</ul>';
const knopf = (text, url, farbe) => '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 18px 0"><tr><td style="background:' + farbe + ';border-radius:6px"><a href="' + esc(url) + '" style="display:inline-block;padding:11px 20px;font-size:14px;font-weight:600;color:#ffffff;text-decoration:none">' + esc(text) + '</a></td></tr></table>';
const klein = (text) => '<p style="margin:6px 0 14px 0;font-size:13px;line-height:1.5;color:#6b7280">' + verlinken(text).replace(/\n/g, '<br>') + '</p>';
const datum = (iso, kurz) => {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? String(iso) : d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: kurz ? 'short' : 'medium' }) + ' Uhr';
};
const layout = ({ label, farbe, titel, badge, vorschau, abschnitte }) => {
  const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
  const plakette = badge ? '<div style="margin-top:12px"><span style="display:inline-block;background:#ffffff;color:' + farbe + ';font-size:12px;font-weight:700;padding:4px 10px;border-radius:12px">' + esc(badge) + '</span></div>' : '';
  return '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>' + esc(titel) + '</title></head>'
    + '<body style="margin:0;padding:0;background:#f3f4f6;font-family:' + SCHRIFT + '">'
    + '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#f3f4f6">' + esc(vorschau || titel) + '</div>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6"><tr><td align="center" style="padding:24px 12px">'
    + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden">'
    + '<tr><td style="background:' + farbe + ';padding:22px 26px"><div style="font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:#ffffff;opacity:.9">' + esc(label) + '</div>'
    + '<div style="margin-top:6px;font-size:22px;line-height:1.3;font-weight:700;color:#ffffff">' + esc(titel) + '</div>' + plakette + '</td></tr>'
    + '<tr><td style="padding:24px 26px 12px 26px;font-size:15px;line-height:1.6;color:#1f2937">' + abschnitte.join('') + '</td></tr>'
    + '<tr><td style="padding:14px 26px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.6;color:#6b7280">Automatisch gesendet von n8n am ' + esc(zeit) + ' Uhr<div style="color:#9ca3af">' + ID_ZEILE + '</div></td></tr>'
    + '</table></td></tr></table></body></html>';
};
const e = $input.item.json;
const zeilen = String(e.body).split('\n');
const rohdaten = zeilen.filter((z) => /^- [^:]+: /.test(z)).map((z) => {
  const i = z.indexOf(': ');
  return [z.slice(2, i), z.slice(i + 2)];
});
const empfangen = (zeilen.find((z) => z.startsWith('Empfangen: ')) || '').slice(11);
const zeit = empfangen ? datum(empfangen) : '-';
const html = layout({
  label: 'ALAMOS · Einsatzalarm',
  farbe: FARBEN.rot,
  titel: e.title,
  badge: 'Neuer Alarm',
  vorschau: e.title,
  abschnitte: [
    absaetze('Neuer Einsatzalarm von ALAMOS AMweb. Das hat der Webhook mitgeliefert:'),
    felder(rohdaten.concat([['Empfangen', zeit]])),
    klein('Das Zammad-Ticket wird parallel angelegt.'),
  ],
});
return { json: { mailAn: MAIL_AN, mailVon: MAIL_VON, betreff: e.title, text: mitId(e.body), html } };
